<template>
  <div class="v3-world-tour v3-screen" data-reference-node-id="1025:16528">
    <sf-page-layout :asset="workoutAsset" extended :home-indicator="false">
      <template #header><sf-user-toolbar :avatar="(user&&user.avatarUrl)||workoutAsset('imgEllipse305')" :badge="workoutAsset('img40')" :actions="toolbarActions" @action="toolbarAction"><template #leading><strong v-if="user&&user.name" class="v3-world-tour__user">{{ user.name }}</strong></template></sf-user-toolbar></template>
      <sf-segmented-control value="world" :items="modes" label="Workout modes" @change="modeAction"/>
      <template v-if="!scene&&!equipment&&!query">
        <button v-if="contents.length" class="v3-world-tour__hero" type="button" :aria-label="'View '+contents[0].name" @click="$emit('action','open-world-tour:'+contents[0].id)"><img :src="contents[0].coverUrl||asset('world-tour-cover')" alt=""/><span>{{ contents[0].tier==='free'?'Free':'Premium' }}</span></button>
        <div class="v3-world-tour__indicator" aria-hidden="true"><i/><i/><i/></div>
      </template>
      <section class="v3-world-tour__scenes"><h2>Scene</h2><div><button v-for="item in scenes" :key="item.name" type="button" :aria-pressed="scene===item.name?'true':'false'" @click="scene=scene===item.name?'':item.name"><img :src="asset(item.image)" alt=""/><span>{{ item.name }}</span></button></div></section>
      <section class="v3-world-tour__equipment"><h2>Equipment</h2><div><button v-for="item in equipmentTypes" :key="item.name" type="button" :aria-pressed="equipment===item.name?'true':'false'" @click="equipment=equipment===item.name?'':item.name"><img :src="asset(item.image)" alt=""/><span>{{ item.name }}</span></button></div></section>
      <section class="v3-world-tour__routes"><header><h2>{{ scene||equipment?'Matching routes':'Explore routes' }}</h2><button v-if="scene||equipment||query" type="button" @click="scene='';equipment='';query=''">Clear filters</button></header><button v-for="route in visibleRoutes" :key="route.id" class="v3-world-tour__route" type="button" :data-content-id="route.id" :aria-label="'View '+route.name" @click="$emit('action','open-world-tour:'+route.id)"><img :src="route.coverUrl||asset('world-tour-cover')" alt=""/><div><span>{{ route.tier==='free'?'Free':'Premium' }}</span><h3>{{ route.name }}</h3><p>{{ route.durationMinutes }} min <template v-if="route.scene">· {{ route.scene }}</template></p></div><sf-icon name="arrow" :size="17"/></button><sf-feedback v-if="!visibleRoutes.length" title="No routes available" tone="empty"/></section>
      <template #footer><sf-bottom-navigation :items="navigation" active="workout" @select="$emit('action',$event.action)"/></template>
    </sf-page-layout>
    <sf-sheet v-model="searching" title="Search World Tours" contained :resizable="false"><sf-search-field v-model="query" label="Search routes" placeholder="Search routes"/><sf-menu-row v-for="route in visibleRoutes" :key="route.id" :label="route.name" :description="route.durationMinutes+' min'" @click="openRoute(route.id)"/><sf-feedback v-if="!visibleRoutes.length" title="No matching routes" tone="empty"/></sf-sheet>
  </div>
</template>
<script>
import {SfPageLayout,SfUserToolbar,SfSegmentedControl,SfBottomNavigation,SfFeedback,SfIcon,SfSheet,SfSearchField,SfMenuRow} from '@/design-system'
import {sceneAsset,workoutNavigation} from '@/design-system/assets/v3-scenes'
export default {
  components:{SfPageLayout,SfUserToolbar,SfSegmentedControl,SfBottomNavigation,SfFeedback,SfIcon,SfSheet,SfSearchField,SfMenuRow},props:{contents:{type:Array,default:()=>[]},user:Object},
  data(){return {scene:'',equipment:'',query:'',searching:false,navigation:workoutNavigation,modes:[{value:'course',label:'Course'},{value:'world',label:'World Tour'},{value:'free',label:'Free Mode'}],scenes:[{name:'Riding',image:'scene-riding'},{name:'Boating',image:'scene-boating'},{name:'Running',image:'scene-running'}],equipmentTypes:[{name:'Indoor Ride',image:'equipment-bike'},{name:'Rower',image:'equipment-rower'},{name:'Treadmill',image:'equipment-treadmill'}]}},
  computed:{visibleRoutes(){return this.contents.filter(route=>(!this.scene||route.scene===this.scene)&&(!this.equipment||route.equipment===this.equipment)&&(route.name+' '+(route.description||'')).toLowerCase().includes(this.query.toLowerCase()))},toolbarActions(){return [{id:'search',label:'Search routes',icon:this.workoutAsset('img8')},{id:'plan',label:'Training calendar',icon:this.workoutAsset('imgGroup259')},{id:'existing-free-mode',label:'Free workout mode',icon:this.workoutAsset('imgGroup412')}]}},
  methods:{asset(name){return process.env.BASE_URL+'assets/figma/content-review/'+name+'.png'},workoutAsset(name){return sceneAsset('workout',name)},toolbarAction(action){if(action==='search')this.searching=true;else this.$emit('action',action)},modeAction(value){if(value!=='world')this.$emit('action',value==='course'?'workout':'existing-free-mode')},openRoute(id){this.searching=false;this.$emit('action','open-world-tour:'+id)}}
}
</script>
<style scoped>
