ur__equipment button[aria-pressed=true] img{outline:2px solid #e68e80;outline-offset:3px}.v3-world-tour__equipment{margin-top:26px}.v3-world-tour__routes{margin-top:28px}.v3-world-tour__routes>header{display:flex;justify-content:space-between;align-items:baseline}.v3-world-tour__routes>header>button{border:0;background:none;font-size:11px;color:#c38175;cursor:pointer}.v3-world-tour__route{display:flex;align-items:center;gap:13px;width:100%;padding:11px;border:1px solid #f0e9f1;border-radius:15px;background:#ffffffac;margin-bottom:12px;text-align:left;cursor:pointer}.v3-world-tour__route>img{width:67px;height:77px;border-radius:10px;object-fit:cover}.v3-world-tour__route>div{flex:1}.v3-world-tour__route div>span{font-size:9px;color:#b9926e}.v3-world-tour__route h3{font-size:14px;line-height:21px;color:#93799f;margin:4px 0;font-weight:600}.v3-world-tour__route p{font-size:11px;color:#b29dbc;margin:0}.v3-world-tour__route>.sf-icon{color:#c8b6d0}
.v3-world-tour__user{font-size:13px;line-height:20px;font-weight:600;color:#8d709a;max-width:110px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
</style>